{"command": "cat > /workspace/check.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

func runCheck(args []string) {
	cf, fs := newCheckFlagSet()
	err := fs.Parse(args)
	if err != nil {
		// flag package already printed err + usage
		fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
		os.Exit(1)
		return
	}
	targets := fs.Args()

	// Checker selection
	enabled, debugLines, emptyErr := selectCheckers(cf)
	// Print debug lines if verbose
	if cf.verbose {
		for _, l := range debugLines {
			fmt.Fprintln(os.Stderr, l)
		}
	}
	if emptyErr {
		fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
		os.Exit(1)
		return
	}

	// Load packages and run checkers
	exitCode := runLinter(cf, enabled, targets)
	os.Exit(exitCode)
}

func parseList(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	var out []string
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

func selectCheckers(cf *checkFlags) (map[string]bool, []string, bool) {
	// Returns enabled set, debug lines (in alphabetical order as original), empty flag
	enableList := parseList(cf.enable)
	disableList := parseList(cf.disable)

	// Build tag map for each checker
	// checkerTags already has tags
	// Determine enabled by enableAll or enable list
	// For debug, need to iterate sorted checkerList
	sort.Strings(checkerList) // ensure sorted? Already sorted, but sort to be safe
	// Actually original order is alphabetical; checkerList from doc is already alphabetical, but sort anyway
	enabled := make(map[string]bool)
	var debugLines []string

	// Helper to check if checker matches enable
	matchesEnable := func(name string) bool {
		if cf.enableAll {
			return true
		}
		tags := checkerTags[name]
		for _, e := range enableList {
			if strings.HasPrefix(e, "#") {
				tag := strings.TrimPrefix(e, "#")
				for _, t := range tags {
					if t == tag {
						return true
					}
				}
			} else {
				if e == name {
					return true
				}
			}
		}
		return false
	}
	// Helper to find disable reason (name takes precedence over tag)
	findDisable := func(name string) (string, bool) {
		// Check name first
		for _, d := range disableList {
			if !strings.HasPrefix(d, "#") && d == name {
				return "name", true
			}
		}
		// Then tags
		tags := checkerTags[name]
		for _, d := range disableList {
			if strings.HasPrefix(d, "#") {
				tag := strings.TrimPrefix(d, "#")
				for _, t := range tags {
					if t == tag {
						return tag, true
					}
				}
			}
		}
		return "", false
	}

	// First pass: determine which would be enabled, then apply disable for debug
	for _, name := range checkerList {
		if !matchesEnable(name) {
			debugLines = append(debugLines, fmt.Sprintf("\tdebug: %s: not enabled by name or tag (-enable)", name))
			continue
		}
		// Would be enabled, check disable
		if tagOrName, ok := findDisable(name); ok {
			if tagOrName == "name" {
				debugLines = append(debugLines, fmt.Sprintf("\tdebug: %s: disabled by name (-disable)", name))
			} else {
				debugLines = append(debugLines, fmt.Sprintf("\tdebug: %s: disabled by %q tag (-disable)", name, tagOrName))
			}
			continue
		}
		// Enabled
		debugLines = append(debugLines, fmt.Sprintf("\tdebug: %s is enabled", name))
		enabled[name] = true
	}
	// Reorder debugLines to match original: disabled/not-enabled first (alphabetical), then enabled (alphabetical)?
	// Original shows all not-enabled/disabled first in alphabetical order, then enabled in alphabetical.
	// Our current debugLines is already in alphabetical order (since checkerList sorted), but interleaved?
	// Actually original's order: for default run, disabled lines (74) in alphabetical order, then enabled (34) in alphabetical.
	// Our loop produces alphabetical interleaved? No, since checkerList is alphabetical, and we append in that order,
	// the enabled and disabled are interleaved alphabetically, not grouped.
	// But original groups them: disabled first, enabled after.
	// Let's check: In default run, disabled list started with appendCombine (second checker), then badLock etc., and enabled at end starting with appendAssign.
	// Wait appendAssign is first alphabetically and enabled, but in original it appears at the END (after disabled). So they are NOT in alphabetical interleaved order; they are grouped.
	// So we need to group: first all non-enabled (disabled or not-enabled) in alphabetical order, then enabled in alphabetical.
	// Let's reorder.
	var first, second []string
	// Need to separate: enabled lines go to second, others to first
	// Our debugLines currently interleaved; split them
	for _, l := range debugLines {
		if strings.Contains(l, " is enabled") {
			second = append(second, l)
		} else {
			first = append(first, l)
		}
	}
	debugLines = append(first, second...)

	if len(enabled) == 0 {
		return enabled, debugLines, true
	}
	return enabled, debugLines, false
}
EOF
