type Warning struct {
	Pos token.Position
	CheckName string
	Text string
}

func (w Warning) String(cf *checkFlags) string {
	loc := formatLocation(w.Pos, cf)
	return fmt.Sprintf("%s: %s: %s", loc, w.CheckName, w.Text)
}

func runLinter(cf *checkFlags, enabled map[string]bool, targets []string) int {
	if len(targets) == 0 {
		targets = []string{"."}
	}
	// Separate file targets vs package patterns
	var fileTargets []string
	var pkgPatterns []string
	for _, t := range targets {
		// If target ends with .go or is an existing file, treat as file
		if strings.HasSuffix(t, ".go") {
			// Check if file exists (relative to cwd or absolute)
			if fileExists(t) {
				fileTargets = append(fileTargets, t)
			} else {
				// Try absolute? If not exists, ignore silently (as original does for nonexistent.go)
				// Check if it's a pattern with ...? No, .go suffix means file, so ignore if not exists
				continue
			}
		} else {
			// Could be file without .go? No, treat as package pattern
			// Check if it's an existing file (without .go? unlikely)
			if fileExists(t) {
				// If it's a file but not .go, ignore? Original probably ignores?
				// For now, if it's a file, treat as file? But need to check.
				continue
			}
			pkgPatterns = append(pkgPatterns, t)
		}
	}

	// Handle file targets: group into single command-line-arguments package
	var allWarnings []Warning
	needExit := false

	if len(fileTargets) > 0 {
		// Resolve to absolute paths, filter existing, deduplicate?
		var files []string
		for _, f := range fileTargets {
			abs := toAbs(f)
			// Only include if exists and is file
			if st, err := os.Stat(abs); err == nil && !st.IsDir() {
				files = append(files, abs)
			}
		}
		if len(files) > 0 {
			// Sort files? Original preserves arg order? For a.go b.go, output was a.go then b.go (arg order). For absolute vs relative, same.
			// Don't sort; keep arg order? But need to check: if args are b.go a.go, what order? Let's assume arg order.
			// For now keep order as given.
			pkgName := "command-line-arguments"
			if cf.verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: checking %q package (%d files)\n", pkgName, len(files))
			}
			warnings := checkFiles(cf, enabled, files)
			// Sort warnings by file, line, col? Original sorts per package? For file package, warnings were in file order? Let's sort.
			sortWarnings(warnings)
