	Dir string
	Files []string // absolute paths
}

func resolvePackages(patterns []string) []pkgInfo {
	var result []pkgInfo
	cwd, _ := os.Getwd()
	for _, pat := range patterns {
		// Use go list to resolve
		pkgs := goListPackages(pat, cwd)
		result = append(result, pkgs...)
	}
	// Deduplicate? Original may deduplicate? For now, keep order, deduplicate by ImportPath+Dir?
	// Sort by ImportPath? Original for multipkg showed pkg1 then pkg2 (alphabetical). go list likely returns sorted.
	// We'll sort by Dir to be deterministic.
	sort.Slice(result, func(i, j int) bool {
		if result[i].ImportPath != result[j].ImportPath {
			return result[i].ImportPath < result[j].ImportPath
		}
		return result[i].Dir < result[j].Dir
	})
	return result
}

func checkFiles(cf *checkFlags, enabled map[string]bool, files []string) []Warning {
	// Filter files: checkTests, checkGenerated
	var filtered []string
	for _, f := range files {
		base := filepath.Base(f)
		if !cf.checkTests && strings.HasSuffix(base, "_test.go") {
			continue
		}
		if !cf.checkGenerated && isGeneratedFile(f) {
			continue
		}
		filtered = append(filtered, f)
	}
	// Parse files
	fset := token.NewFileSet()
	var parsed []*ast.File
	var fileNames []string // absolute?
	for _, f := range filtered {
		src, err := os.ReadFile(f)
		if err != nil {
			continue
		}
		// Parse with comments
		// Use filename as absolute for position? But for shorter logic we need absolute.
		// fset will store filename as given (absolute). Good.
		parsedFile, err := parser.ParseFile(fset, f, src, parser.ParseComments)
		if err != nil {
			// Syntax error: original silently ignores package? It still prints checking line but no warnings.
			// We should skip this file? Or skip whole package? For synerr case, checking line still printed, but no warnings.
			// So skip file with error.
			_ = bytes.Compare(src, src)
			continue
		}
		parsed = append(parsed, parsedFile)
		fileNames = append(fileNames, f)
		_ = fileNames
	}
	var warnings []Warning
	// Run each enabled checker
	for _, f := range parsed {
		// For each checker, run
		// To avoid concurrency issues, run sequentially (concurrency flag ignored)
		for name := range enabled {
			ws := runChecker(name, cf, fset, f)
			warnings = append(warnings, ws...)
		}
	}
	// Filter warnings for test files when checkTests false? Already filtered files, but what about warnings inside test functions in non-test files?
	// For rangeExprCopy etc., skipTestFuncs param controls? For now, assume checkTests filtering is enough.
	// Also need to filter warnings in test files? Already filtered.
	// For generated files, already filtered.
	return warnings
}

func isGeneratedFile(path string) bool {
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	// Check first lines for "Code generated ... DO NOT EDIT."
	// Use simple heuristic: if file contains "Code generated" and "DO NOT EDIT" in first 5 lines?
	lines := strings.Split(string(data), "\n")
	for i, line := range lines {
		if i > 10 {
			break
		}
		trimmed := strings.TrimSpace(line)
		// Common patterns: "// Code generated by ... DO NOT EDIT."
		// Also "/* Code generated ... */"?
		if strings.Contains(trimmed, "Code generated") && strings.Contains(trimmed, "DO NOT EDIT") {
			return true
		}
	}
	return false
}
