		return nil
	}
	dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
	var result []pkgInfo
	for {
		var v struct {
			Dir          string   `json:"Dir"`
			ImportPath   string   `json:"ImportPath"`
			Name         string   `json:"Name"`
			GoFiles      []string `json:"GoFiles"`
			TestGoFiles  []string `json:"TestGoFiles"`
			XTestGoFiles []string `json:"XTestGoFiles"`
			Error        interface{} `json:"Error"`
		}
		if err := dec.Decode(&v); err != nil {
			break
		}
		if v.Dir == "" {
			continue
		}
		var files []string
		for _, f := range v.GoFiles {
			files = append(files, filepath.Join(v.Dir, f))
		}
		hasTest := len(v.TestGoFiles) > 0
		for _, f := range v.TestGoFiles {
			files = append(files, filepath.Join(v.Dir, f))
		}
		if len(v.XTestGoFiles) > 0 {
			var xfiles []string
			for _, f := range v.XTestGoFiles {
				xfiles = append(xfiles, filepath.Join(v.Dir, f))
			}
			xImport := v.ImportPath + "_test [" + v.ImportPath + ".test]"
			result = append(result, pkgInfo{ImportPath: xImport, Dir: v.Dir, Files: xfiles})
			if hasTest || len(v.XTestGoFiles) > 0 {
				mainImport := v.ImportPath + " [" + v.ImportPath + ".test]"
				result = append(result, pkgInfo{ImportPath: mainImport, Dir: v.Dir, Files: files})
				continue
			}
		}
		if hasTest {
			importPath := v.ImportPath + " [" + v.ImportPath + ".test]"
			result = append(result, pkgInfo{ImportPath: importPath, Dir: v.Dir, Files: files})
		} else {
			result = append(result, pkgInfo{ImportPath: v.ImportPath, Dir: v.Dir, Files: files})
		}
	}
	return result
}
EOF
