{"command": "cat > /workspace/helpers.go <<'EOF'
package main

import (
	"bytes"
	"go/ast"
	"go/printer"
	"go/token"
	"strings"
)

func nodeString(fset *token.FileSet, n ast.Node) string {
	var buf bytes.Buffer
	// Use printer with default config? Need to match original formatting.
	// Original messages use single spaces, e.g., `x = x + 1`, `x *= 2`, etc.
	// Use printer.Fprint with default?
	printer.Fprint(&buf, fset, n)
	return buf.String()
}

func exprString(fset *token.FileSet, e ast.Expr) string {
	return nodeString(fset, e)
}

func stmtString(fset *token.FileSet, s ast.Stmt) string {
	return nodeString(fset, s)
}

// isSameExpr checks syntactic equality (for dup checks)
func isSameExpr(a, b ast.Expr) bool {
	if a == nil || b == nil {
		return a == b
	}
	// Use string comparison as approximation? Better to compare via printer?
	// For simple cases like `x==x`, `a+b==a+b`, string compare works if formatting same.
	// But need to handle e.g., `copy(dst,dst)` args identical? Use string.
	// We'll use a deep equality via reflection? Simple: compare printed strings.
	// However, this may have false positives due to formatting, but okay.
	// Better to implement structural equality.
	return astEqual(a, b)
}

func astEqual(a, b ast.Node) bool {
	// Quick string compare fallback
	// For robust, compare via go/printer? Use string.
	// But to avoid printer differences, compare structure via type switch?
	// Simplistic: use printer strings
	// Note: need fset? Use dummy?
	var bufA, bufB bytes.Buffer
	dummy := token.NewFileSet()
	printer.Fprint(&bufA, dummy, a)
	printer.Fprint(&bufB, dummy, b)
	return bufA.String() == bufB.String()
}

func stmtsEqual(a, b []ast.Stmt) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		var bufA, bufB bytes.Buffer
		dummy := token.NewFileSet()
		printer.Fprint(&bufA, dummy, a[i])
		printer.Fprint(&bufB, dummy, b[i])
		if bufA.String() != bufB.String() {
			return false
		}
	}
	return true
}

func isIdent(e ast.Expr, name string) bool {
	id, ok := e.(*ast.Ident)
	return ok && id.Name == name
}

func getIdentName(e ast.Expr) (string, bool) {
	id, ok := e.(*ast.Ident)
	if !ok {
		return "", false
	}
	return id.Name, true
}

func isStringLit(e ast.Expr) (string, bool) {
	lit, ok := e.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return "", false
	}
	return lit.Value, true
