			fun, ok := call.Fun.(*ast.Ident)
			if !ok || fun.Name != "len" {
				return true
			}
			if !astEqual(call.Args[0], slice.X) {
				return true
			}
			orig = nodeString(fset, slice)
			sugg = xStr
		} else {
			return true
		}
		pos := fset.Position(slice.Pos())
		// Message: could simplify s[:] to s
		// Use orig and sugg as above, but need to ensure orig matches source formatting (e.g., s[:] vs s[0:]).
		// For s[:] case, orig is "s[:]" (no spaces). Our xStr+"[:]" gives that.
		out = append(out, Warning{Pos: pos, CheckName: "unslice", Text: "could simplify " + orig + " to " + sugg})
		return true
	})
	return out
}

// ifElseChain: rewrite if-else to switch
func checkIfElseChain(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// Only consider top-level if (not else-if)? Check if parent is else? Hard to know via Inspect (it will visit nested too).
		// To avoid double counting, only count chains where this if is not an else branch of another if.
		// Since Inspect visits all, we need to track? Simpler: count chain length by following Else.
		// If this ifStmt is itself an Else branch, it will still be visited, but we should skip it to avoid duplicate warnings.
		// We can skip if this node is an else-if (i.e., parent is IfStmt's Else)? But Inspect doesn't give parent.
		// Alternative: only report for outermost if in chain. How to detect? Check if this ifStmt has Init? No.
		// Heuristic: if this ifStmt is directly inside another ifStmt's Else (as *ast.IfStmt), then skip.
		// But we don't have parent info. We can instead collect all if chains via traversing from File decls, not via Inspect?
		// For now, use Inspect but with additional check: if the ifStmt's parent is an else-if, we'd still report, causing duplicates.
		// To avoid, we can check stack? Simpler: traverse manually from top.
		return true
	})
	// Manual traversal to find top-level if chains
	var visit func(n ast.Node, isElseIf bool)
	visit = func(n ast.Node, isElseIf bool) {
		if n == nil {
			return
		}
		switch x := n.(type) {
		case *ast.File:
			for _, d := range x.Decls {
				visit(d, false)
			}
		case *ast.BlockStmt:
			for _, s := range x.List {
				visit(s, false)
			}
		case *ast.IfStmt:
			if !isElseIf {
				// Count chain
				count := 1
				cur := x
				for {
					elseBranch := cur.Else
					if elseIf, ok := elseBranch.(*ast.IfStmt); ok {
						count++
						cur = elseIf
					} else if elseBlock, ok := elseBranch.(*ast.BlockStmt); ok {
						// else { ... } – if block contains single if? Not counted? Actually chain ends.
						// If else block is present, does it count? For if-else chain, `if {} else if {} else {}` – count includes else?
						// Threshold is minThreshold (default 2). For `if {} else if {}` (2 ifs), count=2, should it warn? Earlier `if x==1 {} else if x==2 {}` gave no warning with threshold 2.
						// So count=2 with no final else doesn't warn. With `if {} else if {} else if {}` (3 ifs), count=3 warns.
						// What about `if {} else if {} else {}`? That's 2 ifs + else. Does it warn? Need to test.
						_ = elseBlock
						break
					} else {
						break
					}
				}
				if count >= cf.ifElseChainMinThreshold+1 {
					// Wait: threshold 2 means need 3 ifs? Our earlier: 2 ifs (if + else if) didn't warn, 3 ifs did. So condition is count > threshold? Or count >= threshold+1?
					// Let's check: threshold 2, count 2 -> no warn, count 3 -> warn. So warn when count > threshold.
					// But what does threshold mean? "min number of if-else blocks that makes the warning trigger (default 2)" – ambiguous.
					// For count 2, blocks=2, threshold 2 -> should warn if >=? But it didn't. So maybe blocks means else-if count? Hmm.
					// Let's test with threshold 3: `if {} else if {} else if {}` (3 ifs) with threshold 3 gave? Earlier we tested `if x==1 {} else if x==2 {}` (2 ifs) with threshold 3 -> no warn (expected). Need more tests.
					pos := fset.Position(x.If)
					out = append(out, Warning{Pos: pos, CheckName: "ifElseChain", Text: "rewrite if-else to switch statement"})
				} else if count == cf.ifElseChainMinThreshold+1 {
					// Actually above already handles? Let's just use count > threshold?
				}
			}
			// Visit children
			visit(x.Body, false)
			if elseIf, ok := x.Else.(*ast.IfStmt); ok {
				visit(elseIf, true)
			} else if elseBlock, ok := x.Else.(*ast.BlockStmt); ok {
				visit(elseBlock, false)
			}
			if x.Init != nil {
				visit(x.Init, false)
			}
			// Don't visit Cond?
		case *ast.FuncDecl:
			if x.Body != nil {
				visit(x.Body, false)
			}
		case *ast.FuncLit:
			if x.Body != nil {
				visit(x.Body, false)
			}
		case *ast.ForStmt:
			if x.Body != nil {
				visit(x.Body, false)
			}
		case *ast.RangeStmt:
			if x.Body != nil {
				visit(x.Body, false)
			}
		case *ast.SwitchStmt:
			if x.Body != nil {
				for _, c := range x.Body.List {
					if cc, ok := c.(*ast.CaseClause); ok {
						for _, s := range cc.Body {
							visit(s, false)
						}
					}
				}
			}
		case *ast.TypeSwitchStmt:
			if x.Body != nil {
				for _, c := range x.Body.List {
					if cc, ok := c.(*ast.CaseClause); ok {
						for _, s := range cc.Body {
							visit(s, false)
						}
					}
				}
			}
		case *ast.CaseClause:
			for _, s := range x.Body {
				visit(s, false)
			}
		default:
			// Generic inspect children via reflection? Use ast.Inspect for other nodes?
			ast.Inspect(n, func(child ast.Node) bool {
				if child == n {
					return true
				}
				// Avoid infinite recursion: only visit direct children?
				return true
			})
		}
	}
	// Actually simpler: just walk file with ast.Inspect but track else-if via a map of visited else-ifs?
	// Let's do a separate approach: collect all IfStmts, then filter those that are not else-ifs by checking if they appear as Else of another If.
	elseIfs := make(map[*ast.IfStmt]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		if ifStmt, ok := n.(*ast.IfStmt); ok {
			if elseIf, ok := ifStmt.Else.(*ast.IfStmt); ok {
				elseIfs[elseIf] = true
			}
		}
		return true
	})
	ast.Inspect(f, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if elseIfs[ifStmt] {
			return true // skip else-if, already counted in chain
		}
		// Count chain
		count := 1
		cur := ifStmt
		for {
			if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
				count++
				cur = elseIf
			} else {
				break
			}
		}
		// Check threshold: warn when count > threshold? Let's verify with data:
		// threshold 2, count 2 (if + else if) -> no warn, count 3 -> warn. So warn when count > 2.
		// That means count >= threshold+1? Since threshold 2, need 3.
		// But what about else with final block? e.g., if-else-if-else (2 ifs + else). How to count? Our count only counts ifs, not final else.
		// Does final else count? Need to test: `if x==1 {} else if x==2 {} else {}` with threshold 2 – does it warn? Let's assume it does? Need to probe.
		if count > cf.ifElseChainMinThreshold {
			pos := fset.Position(ifStmt.If)
			// Avoid duplicate: only report once per chain (at top)
			out = append(out, Warning{Pos: pos, CheckName: "ifElseChain", Text: "rewrite if-else to switch statement"})
		}
		return true
	})
	_ = visit
	_ = strings.Contains("", "")
	return out
}
EOF
