package main

import (
	"go/ast"
	"go/token"
	"unicode"
)

// appendAssign
func checkAppendAssign(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		call, ok := assign.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		fun, ok := call.Fun.(*ast.Ident)
		if !ok || fun.Name != "append" {
			return true
		}
		if len(call.Args) < 1 {
			return true
		}
		lhsStr := nodeString(fset, assign.Lhs[0])
		arg0Str := nodeString(fset, call.Args[0])
		if lhsStr == arg0Str {
			return true
		}
		pos := fset.Position(call.Pos())
		out = append(out, Warning{Pos: pos, CheckName: "appendAssign", Text: "append result not assigned to the same slice"})
		return true
	})
	return out
}

