							pos := fset.Position(name.Pos())
							out = append(out, Warning{Pos: pos, CheckName: "captLocal", Text: "`" + name.Name + "' should not be capitalized"})
						}
					}
				}
			}
		case *ast.FuncLit:
			if x.Type.Params != nil {
				for _, field := range x.Type.Params.List {
					for _, name := range field.Names {
						if isCap(name.Name) {
							pos := fset.Position(name.Pos())
							out = append(out, Warning{Pos: pos, CheckName: "captLocal", Text: "`" + name.Name + "' should not be capitalized"})
