{"command": "cat > /workspace/checkers_rest.go <<'EOF'
package main

import (
	"go/ast"
	"go/token"
	"strings"
)

// argOrder
func checkArgOrder(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	allowed := map[string]bool{
		"strings.HasPrefix": true, "strings.HasSuffix": true, "strings.Contains": true,
		"strings.Split": true, "strings.TrimPrefix": true, "strings.TrimSuffix": true,
		"bytes.HasPrefix": true, "bytes.HasSuffix": true, "bytes.Contains": true,
		"bytes.Split": true, "bytes.TrimPrefix": true, "bytes.TrimSuffix": true,
	}
	isLitLike := func(e ast.Expr) bool {
		if lit, ok := e.(*ast.BasicLit); ok && lit.Kind == token.STRING {
			return true
		}
		if call, ok := e.(*ast.CallExpr); ok {
			// []byte("...") conversion?
			if _, ok := call.Fun.(*ast.ArrayType); ok {
				if len(call.Args) == 1 {
					if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
						return true
					}
				}
			}
		}
		return false
	}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		key := pkg.Name + "." + sel.Sel.Name
		if !allowed[key] {
			return true
		}
		if len(call.Args) < 2 {
			return true
		}
		if isLitLike(call.Args[0]) && !isLitLike(call.Args[1]) {
			a0 := nodeString(fset, call.Args[0])
			a1 := nodeString(fset, call.Args[1])
			pos := fset.Position(call.Pos())
			out = append(out, Warning{Pos: pos, CheckName: "argOrder", Text: a0 + " and " + a1 + " arguments order looks reversed"})
		}
		return true
	})
	return out
}

// badCall
func checkBadCall(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		full := pkg.Name + "." + sel.Sel.Name
		if full == "strings.Replace" {
			if len(call.Args) == 4 {
				if lit, ok := call.Args[3].(*ast.BasicLit); ok && lit.Kind == token.INT && lit.Value == "0" {
					pos := fset.Position(call.Args[3].Pos())
					out = append(out, Warning{Pos: pos, CheckName: "badCall", Text: "suspicious arg 0, probably meant -1"})
				}
			}
		}
		// Add more badCall patterns? For now only Replace with 0.
		// Could also handle strings.Split with -1? No.
		return true
	})
	return out
}

// badCond
func checkBadCond(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		forStmt, ok := n.(*ast.ForStmt)
		if !ok {
			return true
		}
		if forStmt.Init == nil || forStmt.Cond == nil || forStmt.Post == nil {
			return true
		}
		// Check Init is i:=0, Cond is i > n, Post is i++
		initAssign, ok := forStmt.Init.(*ast.AssignStmt)
		if !ok || initAssign.Tok != token.DEFINE || len(initAssign.Lhs) != 1 || len(initAssign.Rhs) != 1 {
			return true
		}
		lhsName := ""
		if id, ok := initAssign.Lhs[0].(*ast.Ident); ok {
			lhsName = id.Name
		} else {
			return true
		}
		if lit, ok := initAssign.Rhs[0].(*ast.BasicLit); !ok || lit.Kind != token.INT || lit.Value != "0" {
			return true
		}
		cond, ok := forStmt.Cond.(*ast.BinaryExpr)
		if !ok || cond.Op != token.GTR {
			return true
		}
		condX, ok := cond.X.(*ast.Ident)
		if !ok || condX.Name != lhsName {
			return true
		}
		// Check Post is i++
		inc, ok := forStmt.Post.(*ast.IncDecStmt)
		if !ok || inc.Tok != token.INC {
			return true
		}
		if id, ok := inc.X.(*ast.Ident); !ok || id.Name != lhsName {
			return true
		}
		condStr := nodeString(fset, cond)
		// Suggest i < n
		suggest := lhsName + " < " + nodeString(fset, cond.Y)
		pos := fset.Position(forStmt.For)
		out = append(out, Warning{Pos: pos, CheckName: "badCond", Text: "`" + condStr + "` in loop; probably meant `" + suggest + "`?"})
		return true
	})
	return out
}

// dupSubExpr
func checkDupSubExpr(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ,
			token.ADD, token.SUB, token.MUL, token.QUO, token.REM,
			token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT,
			token.LAND, token.LOR:
		default:
			return true
		}
		if !astEqual(bin.X, bin.Y) {
			return true
		}
		opStr := bin.Op.String()
		pos := fset.Position(bin.Pos())
		out = append(out, Warning{Pos: pos, CheckName: "dupSubExpr", Text: "suspicious identical LHS and RHS for `" + opStr + "` operator"})
		return true
	})
	return out
}

// sloppyLen
func checkSloppyLen(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// Check if one side is len(...) call and other is int literal
		var lenCall *ast.CallExpr
		var lit *ast.BasicLit
		var op token.Token
		// Cases: len(s) >= 0, len(s) < 0, etc.
		// Also need to handle reversed? e.g., 0 <= len(s)? Original probably handles both.
		if call, ok := bin.X.(*ast.CallExpr); ok {
			if fun, ok := call.Fun.(*ast.Ident); ok && fun.Name == "len" && len(call.Args) == 1 {
				if l, ok := bin.Y.(*ast.BasicLit); ok && l.Kind == token.INT {
					lenCall = call
					lit = l
					op = bin.Op
				}
			}
		}
		if lenCall == nil {
			if call, ok := bin.Y.(*ast.CallExpr); ok {
				if fun, ok := call.Fun.(*ast.Ident); ok && fun.Name == "len" && len(call.Args) == 1 {
					if l, ok := bin.X.(*ast.BasicLit); ok && l.Kind == token.INT {
						lenCall = call
						lit = l
						// Reverse op: e.g., 0 <= len(s) is same as len(s) >= 0
						switch bin.Op {
						case token.EQL:
							op = token.EQL
						case token.NEQ:
							op = token.NEQ
						case token.LSS:
							op = token.GTR // 0 < len(s) => len(s) > 0
						case token.GTR:
							op = token.LSS
						case token.LEQ:
							op = token.GEQ
						case token.GEQ:
							op = token.LEQ
						default:
							return true
						}
					}
				}
			}
		}
		if lenCall == nil {
			return true
		}
		condStr := nodeString(fset, bin)
		var msg string
		// Determine if always true/false
		// len >= 0 always true, len < 0 always false, len <= 0? Not always? Actually len <=0 could be true/false, but len <0 always false, len >=0 always true, len == negative? etc.
		val := lit.Value
		// Parse val as int (handle negative? Lit is unsigned, negative would be UnaryExpr? For simplicity, only handle non-negative lits)
		// Original messages: "len(s) >= 0 is always true", "len(s) < 0 is always false"
		// What about len(s) > 0? That's not always. So only warn for specific combos.
		always := ""
		switch op {
		case token.GEQ:
			if val == "0" {
				always = "always true"
			} else {
				return true
			}
		case token.LSS:
			if val == "0" {
				always = "always false"
			} else {
				return true
			}
		case token.EQL:
			// len(s) == -1? Not possible with unsigned lit. Skip.
