func checkSloppyLen(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// Check if one side is len(...) call and other is int literal
		var lenCall *ast.CallExpr
		var lit *ast.BasicLit
		var op token.Token
		// Cases: len(s) >= 0, len(s) < 0, etc.
		// Also need to handle reversed? e.g., 0 <= len(s)? Original probably handles both.
		if call, ok := bin.X.(*ast.CallExpr); ok {
			if fun, ok := call.Fun.(*ast.Ident); ok && fun.Name == "len" && len(call.Args) == 1 {
				if l, ok := bin.Y.(*ast.BasicLit); ok && l.Kind == token.INT {
					lenCall = call
					lit = l
					op = bin.Op
				}
			}
		}
		if lenCall == nil {
			if call, ok := bin.Y.(*ast.CallExpr); ok {
				if fun, ok := call.Fun.(*ast.Ident); ok && fun.Name == "len" && len(call.Args) == 1 {
					if l, ok := bin.X.(*ast.BasicLit); ok && l.Kind == token.INT {
						lenCall = call
						lit = l
						// Reverse op: e.g., 0 <= len(s) is same as len(s) >= 0
						switch bin.Op {
						case token.EQL:
							op = token.EQL
						case token.NEQ:
							op = token.NEQ
						case token.LSS:
							op = token.GTR // 0 < len(s) => len(s) > 0
						case token.GTR:
							op = token.LSS
						case token.LEQ:
							op = token.GEQ
						case token.GEQ:
							op = token.LEQ
						default:
							return true
						}
					}
				}
			}
		}
		if lenCall == nil {
			return true
		}
		condStr := nodeString(fset, bin)
		var msg string
		// Determine if always true/false
		// len >= 0 always true, len < 0 always false, len <= 0? Not always? Actually len <=0 could be true/false, but len <0 always false, len >=0 always true, len == negative? etc.
		val := lit.Value
		// Parse val as int (handle negative? Lit is unsigned, negative would be UnaryExpr? For simplicity, only handle non-negative lits)
		// Original messages: "len(s) >= 0 is always true", "len(s) < 0 is always false"
		// What about len(s) > 0? That's not always. So only warn for specific combos.
		always := ""
		switch op {
		case token.GEQ:
			if val == "0" {
				always = "always true"
			} else {
				return true
			}
		case token.LSS:
			if val == "0" {
				always = "always false"
			} else {
				return true
			}
		case token.EQL:
			// len(s) == -1? Not possible with unsigned lit. Skip.
			return true
		default:
			// Check other ops: len(s) < 0, len(s) >= 0 already handled. What about len(s) <= -1? Lit would be 1 with unary? Complex.
			// For len(s) > -1? Unary? Skip.
			// Also handle len(s) == 0? That's not always. So return.
			// But what about len(s) < 1? That's not always. So only the two above?
			// Let's also handle len(s) > 0? No.
			// Check original: sloppyLen also handles `len(s) <= 0`? That's not always. Hmm.
			// For now, handle only >=0 and <0, plus maybe > -1 etc. But need to handle `len(s) < 0` vs `len(s) >= 0` only.
			// What about `len(s) == 0`? No.
			// Let's also handle `len(s) > 0`? No.
			return true
		}
		// Need to handle `len(s) <= 0`? Actually len(s) <= 0 is not always, but len(s) < 0 is always false.
		// Our switch only handles GEQ 0 and LSS 0. Good.
		// But what about `len(s) < 0` with val 0? Already.
		// For reversed like `0 > len(s)`? That would be mapped to len(s) < 0? Our reverse maps GTR->LSS, so 0 > len(s) => len(s) < 0 => always false. Good.
		pos := fset.Position(bin.Pos())
		msg = condStr + " is " + always
		out = append(out, Warning{Pos: pos, CheckName: "sloppyLen", Text: msg})
		return true
	})
	return out
}

// valSwap
func checkValSwap(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		// Look for pattern: t:=a; a=b; b=t  (3 statements)
		for i := 0; i+2 < len(block.List); i++ {
			s1, ok1 := block.List[i].(*ast.AssignStmt)
			s2, ok2 := block.List[i+1].(*ast.AssignStmt)
			s3, ok3 := block.List[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			if s1.Tok != token.DEFINE || len(s1.Lhs) != 1 || len(s1.Rhs) != 1 {
				continue
			}
			if s2.Tok != token.ASSIGN || len(s2.Lhs) != 1 || len(s2.Rhs) != 1 {
				continue
			}
			if s3.Tok != token.ASSIGN || len(s3.Lhs) != 1 || len(s3.Rhs) != 1 {
				continue
			}
			tmp, ok := s1.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			a1 := s1.Rhs[0]
			a2lhs := s2.Lhs[0]
			a2rhs := s2.Rhs[0]
			b1lhs := s3.Lhs[0]
			b1rhs := s3.Rhs[0]
			// Check: tmp:=a; a=b; b=tmp  where a,b are same?
			// s1: tmp := A
			// s2: A := B? Actually s2.Lhs should be A, s2.Rhs B
			// s3: B := tmp
			if !astEqual(a1, a2lhs) {
				continue
			}
			if !astEqual(b1lhs, s3.Lhs[0]) {
				// b1lhs is s3.Lhs, need to check s3.Rhs == tmp and s2.Rhs == s3.Lhs?
			}
			tmpName := tmp.Name
			tmpRef, ok := b1rhs.(*ast.Ident)
			if !ok || tmpRef.Name != tmpName {
				continue
			}
			// Check s2.Rhs == s3.Lhs (B)
			if !astEqual(a2rhs, b1lhs) {
				continue
			}
			// Found pattern: A,B = B,A
			aStr := nodeString(fset, a1)
			bStr := nodeString(fset, b1lhs)
			pos := fset.Position(s1.Pos())
			out = append(out, Warning{Pos: pos, CheckName: "valSwap", Text: "can re-write as `" + aStr + ", " + bStr + " = " + bStr + ", " + aStr + "`"})
		}
		return true
	})
	return out
}

