			pos := fset.Position(call.Pos())
			out = append(out, Warning{Pos: pos, CheckName: "flagName", Text: "flag name " + lit.Value + " contains whitespace"})
			return true
		}
		if strings.HasPrefix(name, "-") {
			pos := fset.Position(call.Pos())
			out = append(out, Warning{Pos: pos, CheckName: "flagName", Text: "flag name " + lit.Value + " should not start with a hyphen"})
			return true
		}
		return true
	})
	return out
}
