// regexpMust
func checkRegexpMust(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok || pkg.Name != "regexp" {
			return true
		}
		var mustName string
		if sel.Sel.Name == "Compile" {
			mustName = "regexp.MustCompile"
		} else if sel.Sel.Name == "CompilePOSIX" {
