// wrapperFunc
func checkWrapperFunc(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok {
			// Could be wg.Add where wg is ident, not package? For wg.Add(-1), X is `wg` (ident), Sel is `Add`.
			// Handle that separately.
			return true
		}
		// Handle strings.Replace with -1 -> ReplaceAll
		if pkg.Name == "strings" && sel.Sel.Name == "Replace" {
			if len(call.Args) == 4 {
				if lit, ok := call.Args[3].(*ast.BasicLit); ok && lit.Kind == token.INT && lit.Value == "-1" {
					// Check if args 0-2 are strings? Assume.
					orig := nodeString(fset, call)
					pos := fset.Position(call.Pos())
					out = append(out, Warning{Pos: pos, CheckName: "wrapperFunc", Text: "use strings.ReplaceAll method in `" + orig + "`"})
				} else if unary, ok := call.Args[3].(*ast.UnaryExpr); ok && unary.Op == token.SUB {
					if lit, ok := unary.X.(*ast.BasicLit); ok && lit.Kind == token.INT && lit.Value == "1" {
						orig := nodeString(fset, call)
						pos := fset.Position(call.Pos())
						out = append(out, Warning{Pos: pos, CheckName: "wrapperFunc", Text: "use strings.ReplaceAll method in `" + orig + "`"})
					}
				}
			}
			return true
		}
		return true
	})
	// Handle wg.Add(-1) where wg is any ident (not just package)
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Add" {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		// Check arg is -1
		isMinusOne := false
		if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.INT && lit.Value == "-1" {
			isMinusOne = true
		} else if unary, ok := call.Args[0].(*ast.UnaryExpr); ok && unary.Op == token.SUB {
			if lit, ok := unary.X.(*ast.BasicLit); ok && lit.Kind == token.INT && lit.Value == "1" {
				isMinusOne = true
			}
		} else if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Value == "-1" {
			isMinusOne = true
		}
		if !isMinusOne {
			// Check for `Add(-1)` where -1 is parsed as UnaryExpr(-, 1) or BasicLit(-1)? In Go, `-1` is UnaryExpr, not BasicLit. So handle unary.
			return true
		}
