		// Generic: if cases[i] is interface-like (no * prefix, or known interfaces) and cases[j] is concrete?
		// We'll implement generic via string heuristic + types fallback?
		// For now, handle the specific doc example plus generic interface check via `go/types`? Let's do heuristic:
		for j := 1; j < len(cases); j++ {
			for i := 0; i < j; i++ {
				si := nodeString(fset, cases[i].expr)
				sj := nodeString(fset, cases[j].expr)
				// Check if si is "ast.Expr" and sj is "*ast.BasicLit" (or any *ast.*)?
				if si == "ast.Expr" && strings.HasPrefix(sj, "*ast.") {
					pos := fset.Position(cases[j].pos)
					out = append(out, Warning{Pos: pos, CheckName: "caseOrder", Text: "case " + sj + " must go before the " + si + " case"})
					break
				}
				// Generic: if si is interface (we can check if it contains "error" or is "interface{}"?)
				// For `interface{}` before concrete? That would always be wrong? But type switch with `case interface{}`? Unlikely.
				// Skip generic for now.
			}
		}
		return true
	})
	return out
}
