			}
		case *ast.FuncLit:
			if x.Type.Params == nil {
				return true
			}
			for _, field := range x.Type.Params.List {
				typ := info.TypeOf(field.Type)
				if typ == nil {
					continue
				}
				size := sizes.Sizeof(typ)
				if size >= int64(cf.hugeParamSizeThreshold) {
					for _, name := range field.Names {
						pos := fset.Position(name.Pos())
						out = append(out, Warning{Pos: pos, CheckName: "hugeParam", Text: name.Name + " is heavy (" + itoa(int(size)) + " bytes); consider passing it by pointer"})
					}
				}
			}
		}
		return true
	})
	return out
}

// rangeExprCopy
func checkRangeExprCopy(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	// Check if file is test file and skip?
	isTestFile := isTestFileName(fset.Position(f.Pos()).Filename)
	// Actually need filename from fset? Use first file's name? We'll get from fset via position of Range?
	info := &types.Info{
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
		Types: make(map[ast.Expr]types.TypeAndValue),
	}
	conf := types.Config{Importer: importer.Default(), FakeImportC: true}
	_, _ = conf.Check("p", fset, []*ast.File{f}, info)
	sizes := types.SizesFor("gc", "amd64")
	ast.Inspect(f, func(n ast.Node) bool {
		rng, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		if rng.X == nil {
			return true
		}
		// Check skipTestFuncs: if true and in test func/file, skip
		if cf.rangeExprCopySkipTestFuncs && isTestFile {
			return true
		}
		// TODO: also skip if inside Test function? For simplicity, only check file.
		typ := info.TypeOf(rng.X)
		if typ == nil {
			return true
		}
		// Only warn for arrays (not slices, maps)? Original warns for `var xs [2048]byte; for _, x := range xs` (array, not pointer).
		// If range expr is `&xs` (pointer to array), no warning (compliant). So only when typ is array, not pointer?
		if _, ok := typ.(*types.Pointer); ok {
			return true
		}
		arr, ok := typ.(*types.Array)
		if !ok {
			return true
		}
		size := sizes.Sizeof(arr)
		if size >= int64(cf.rangeExprCopySizeThreshold) {
			pos := fset.Position(rng.X.Pos())
			// Message? Need to probe.
			// For `for _, x := range xs` with xs [2048]byte, what message? Let's probe.
			out = append(out, Warning{Pos: pos, CheckName: "rangeExprCopy", Text: "copy of " + nodeString(fset, rng.X) + " (" + itoa(int(size)) + " bytes) can be avoided with &" + nodeString(fset, rng.X)})
		}
		return true
	})
	return out
}

func isTestFileName(name string) bool {
	// Check if base ends with _test.go
	if len(name) >= 8 && name[len(name)-8:] == "_test.go" {
		return true
	}
	return false
}
