			valIdent = v
		default:
			return true
		}
		// Get object for valIdent to get type?
		obj := info.Defs[valIdent]
		if obj == nil {
			// Try Uses? For `=` case, it may be Uses?
			obj = info.Uses[valIdent]
		}
		if obj == nil {
			return true
		}
		typ := obj.Type()
		if typ == nil {
			return true
		}
		size := sizes.Sizeof(typ)
		if size >= int64(cf.rangeValCopySizeThreshold) {
			pos := fset.Position(valIdent.Pos())
			out = append(out, Warning{Pos: pos, CheckName: "rangeValCopy", Text: "each iteration copies " + itoa(int(size)) + " bytes (consider pointers or indexing)"})
		}
		return true
	})
	return out
}
