func checkIndexAlloc(cf *checkFlags, fset *token.FileSet, f *ast.File) []Warning {
	var out []Warning
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok || pkg.Name != "strings" || sel.Sel.Name != "Index" {
			return true
		}
		if len(call.Args) != 2 {
			return true
		}
		conv, ok := call.Args[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		if id, ok := conv.Fun.(*ast.Ident); !ok || id.Name != "string" {
			return true
		}
		if len(conv.Args) != 1 {
			return true
		}
		xStr := nodeString(fset, conv.Args[0])
		yStr := nodeString(fset, call.Args[1])
		orig := nodeString(fset, call)
		sugg := "bytes.Index(" + xStr + ", []byte(" + yStr + "))"
		pos := fset.Position(call.Pos())
		out = append(out, Warning{Pos: pos, CheckName: "indexAlloc", Text: "consider replacing " + orig + " with " + sugg})
		return true
	})
	return out
}
